using System.Reflection.Metadata;using System.Reflection.PortableExecutable;using System.Text.Json;
var root=args[0];var filter=args.Length>1?args[1]:"Placement|Session|Map|Simulation|Savegame|Mod";
var pattern=new System.Text.RegularExpressions.Regex(filter);var results=new List<object>();
foreach(var path in Directory.GetFiles(root,"*.dll").Where(p=>Path.GetFileName(p).StartsWith("Game.")||Path.GetFileName(p)=="SPZGameAssembly.dll"||Path.GetFileName(p)=="MainMenuAssembly.dll"||Path.GetFileName(p)=="Core.dll")){
 using var stream=File.OpenRead(path);using var pe=new PEReader(stream);if(!pe.HasMetadata)continue;var md=pe.GetMetadataReader();
 foreach(var h in md.TypeDefinitions){var t=md.GetTypeDefinition(h);var name=md.GetString(t.Namespace)+"."+md.GetString(t.Name);if(!pattern.IsMatch(name))continue;
 results.Add(new{assembly=Path.GetFileName(path),name,attributes=t.Attributes.ToString(),methods=t.GetMethods().Select(mh=>{var m=md.GetMethodDefinition(mh);return new{name=md.GetString(m.Name),attributes=m.Attributes.ToString(),parameters=m.GetParameters().Select(ph=>md.GetString(md.GetParameter(ph).Name)).ToArray(),signature=Convert.ToHexString(md.GetBlobBytes(m.Signature)),body=m.RelativeVirtualAddress==0?null:Convert.ToHexString(pe.GetMethodBody(m.RelativeVirtualAddress).GetILBytes()),calls=m.RelativeVirtualAddress==0?null:Calls.Read(md,pe.GetMethodBody(m.RelativeVirtualAddress).GetILBytes()),types=m.DecodeSignature(new Types(md),null).ParameterTypes.ToArray(),returns=m.DecodeSignature(new Types(md),null).ReturnType};}).ToArray(),fields=t.GetFields().Select(fh=>{var f=md.GetFieldDefinition(fh);return new{name=md.GetString(f.Name),attributes=f.Attributes.ToString(),type=f.DecodeSignature(new Types(md),null)};}).ToArray()});
 }}Console.WriteLine(JsonSerializer.Serialize(results,new JsonSerializerOptions{WriteIndented=true}));

sealed class Types(MetadataReader md):ISignatureTypeProvider<string,object>{
 public string GetArrayType(string e,ArrayShape s)=>e+"[]";public string GetByReferenceType(string e)=>e+"&";public string GetFunctionPointerType(MethodSignature<string>s)=>"fn";public string GetGenericInstantiation(string t,System.Collections.Immutable.ImmutableArray<string>a)=>t+"<"+string.Join(",",a)+">";public string GetGenericMethodParameter(object c,int i)=>"!!"+i;public string GetGenericTypeParameter(object c,int i)=>"!"+i;public string GetModifiedType(string m,string u,bool r)=>u;public string GetPinnedType(string e)=>e;public string GetPointerType(string e)=>e+"*";public string GetPrimitiveType(PrimitiveTypeCode t)=>t.ToString();public string GetSZArrayType(string e)=>e+"[]";public string GetTypeFromDefinition(MetadataReader r,TypeDefinitionHandle h,byte k){var t=r.GetTypeDefinition(h);return r.GetString(t.Namespace)+"."+r.GetString(t.Name);}public string GetTypeFromReference(MetadataReader r,TypeReferenceHandle h,byte k){var t=r.GetTypeReference(h);return r.GetString(t.Namespace)+"."+r.GetString(t.Name);}public string GetTypeFromSpecification(MetadataReader r,object c,TypeSpecificationHandle h,byte k)=>r.GetTypeSpecification(h).DecodeSignature(this,c);
}

static class Calls {
 static readonly Dictionary<ushort,System.Reflection.Emit.OpCode> ops=typeof(System.Reflection.Emit.OpCodes).GetFields().Where(f=>f.FieldType==typeof(System.Reflection.Emit.OpCode)).Select(f=>(System.Reflection.Emit.OpCode)f.GetValue(null)).ToDictionary(o=>unchecked((ushort)o.Value));
 public static string[] Read(MetadataReader md,byte[] il){var r=new List<string>();int i=0;while(i<il.Length){ushort k=il[i++];if(k==254)k=(ushort)(0xfe00|il[i++]);if(!ops.TryGetValue(k,out var o))break;int size=o.OperandType switch{System.Reflection.Emit.OperandType.InlineNone=>0,System.Reflection.Emit.OperandType.ShortInlineBrTarget or System.Reflection.Emit.OperandType.ShortInlineI or System.Reflection.Emit.OperandType.ShortInlineVar=>1,System.Reflection.Emit.OperandType.InlineVar=>2,System.Reflection.Emit.OperandType.InlineI8 or System.Reflection.Emit.OperandType.InlineR=>8,System.Reflection.Emit.OperandType.InlineSwitch=>4+4*BitConverter.ToInt32(il,i),_=>4};if(size==4){int token=BitConverter.ToInt32(il,i);try{if(o.OperandType==System.Reflection.Emit.OperandType.InlineString)r.Add("string:"+md.GetUserString(System.Reflection.Metadata.Ecma335.MetadataTokens.UserStringHandle(token&0xffffff)));else if(o.OperandType==System.Reflection.Emit.OperandType.InlineMethod){var h=System.Reflection.Metadata.Ecma335.MetadataTokens.EntityHandle(token);if(h.Kind==HandleKind.MemberReference){var m=md.GetMemberReference((MemberReferenceHandle)h);r.Add(md.GetString(m.Name));}else if(h.Kind==HandleKind.MethodDefinition){var m=md.GetMethodDefinition((MethodDefinitionHandle)h);r.Add(md.GetString(m.Name));}}}catch{}}i+=size;}return r.ToArray();}
}
